function RoomScreen({ snapshot }: { snapshot: DashboardSnapshot }) {
  const candles = snapshot.candles.slice(-40);
  const plot = { x: 196, y: 74, w: 648, h: 146 };
  const min = Math.min(...candles.map((candle) => candle.low), snapshot.price);
  const max = Math.max(...candles.map((candle) => candle.high), snapshot.price);
  const range = max - min || 1;
  const slot = plot.w / Math.max(1, candles.length);
  const body = Math.max(3, Math.min(8, slot * 0.5));
  const yFor = (value: number): number => plot.y + (1 - (value - min) / range) * plot.h;
  const maxVolume = Math.max(...candles.map((candle) => candle.volume), 1);
  const closeLine = candles
    .map((candle, index) => `${index === 0 ? "M" : "L"}${(plot.x + slot * (index + 0.5)).toFixed(1)},${yFor(candle.close).toFixed(1)}`)
    .join(" ");

  return (
    <g>
      <rect x="158" y="34" width="718" height="264" rx="7" fill="#0a0610" stroke="#5d3274" strokeWidth="1.5" />
      <rect x="166" y="42" width="702" height="248" rx="3" fill="#07050b" stroke="#2d1a3a" />
      <text x="184" y="58" className="room-screen-title" fill="#d9cde2">
        DOPE / USD - 5M
      </text>
      <text x="558" y="58" className="room-screen-title" fill="#7ff7b2">
        {snapshot.sessionTime}
      </text>
      <text x="850" y="58" textAnchor="end" className="room-screen-title" fill="#ff5d8f">
        ● LIVE
      </text>
      <line x1="174" x2="860" y1="64" y2="64" stroke="#2a1833" />

      <g clipPath="url(#screen-clip)">
        {[0, 0.25, 0.5, 0.75, 1].map((tick) => {
          const y = plot.y + plot.h * tick;
          const value = max - range * tick;
          return (
            <g key={`screen-grid-${tick}`}>
              <line x1={plot.x} x2={plot.x + plot.w} y1={y} y2={y} stroke="#1a2520" strokeWidth="0.7" />
              <text x={plot.x + plot.w - 3} y={y - 3} textAnchor="end" className="room-axis">
                {value.toFixed(5)}
              </text>
            </g>
          );
        })}
        {candles.map((candle, index) => {
          const x = plot.x + slot * (index + 0.5);
          const openY = yFor(candle.open);
          const closeY = yFor(candle.close);
          const rising = candle.close >= candle.open;
          const top = Math.min(openY, closeY);
          const volumeH = (candle.volume / maxVolume) * 24;
          return (
            <g key={`screen-candle-${candle.t}`}>
              <line x1={x} x2={x} y1={yFor(candle.high)} y2={yFor(candle.low)} stroke={rising ? "#66e6a0" : "#ff5d8f"} strokeWidth="1" opacity="0.85" />
              <rect
                x={x - body / 2}
                y={top}
                width={body}
                height={Math.max(1.5, Math.abs(closeY - openY))}
                fill={rising ? "#66e6a0" : "#ff5d8f"}
                opacity="0.9"
              />
              <rect
                x={x - body / 2}
                y={plot.y + plot.h - 26 - volumeH + 26}
                width={body}
                height={Math.max(1, Math.min(24, volumeH))}
                fill={rising ? "#2b7b5d" : "#7c2b49"}
                opacity="0.45"
              />
            </g>
          );
        })}
        <path d={closeLine} fill="none" stroke="#b7ffd8" strokeWidth="1.25" opacity="0.8" />
        <line x1={plot.x} x2={plot.x + plot.w} y1={yFor(snapshot.price)} y2={yFor(snapshot.price)} stroke="#ff7ab4" strokeWidth="0.9" strokeDasharray="3 4" />
        <rect x={plot.x + plot.w - 66} y={yFor(snapshot.price) - 8} width="66" height="15" fill="#ff3b9d" />
        <text x={plot.x + plot.w - 4} y={yFor(snapshot.price) + 3.5} textAnchor="end" className="room-price-tag">
          {snapshot.price.toFixed(5)}
        </text>
        <rect className="screen-sweep" x={plot.x} y={plot.y} width={plot.w} height="18" fill="#b9ffdf" opacity="0.06" />
      </g>

      <line x1="174" x2="860" y1="228" y2="228" stroke="#24162f" />
      <text x="184" y="243" className="room-screen-foot">
        P&amp;L {signed(snapshot.pnl, 0)} / TICKETS {snapshot.fills.toLocaleString("en-US")} / BOOKS 8
      </text>
      <text x="184" y="258" className="room-screen-foot" fill="#8a769a">
        HOLDERS {snapshot.holders} / MC $1.45M / {compact(snapshot.volume24h)} VOL
      </text>
      <text x="850" y="243" textAnchor="end" className={`room-screen-foot ${snapshot.changePct >= 0 ? "room-tone-mint" : ""}`}>
        {signed(snapshot.changePct, 2)}%
      </text>
      <text x="850" y="258" textAnchor="end" className="room-screen-foot" fill="#8a769a">
        CRAWLER THINK
      </text>
      <rect x="184" y="268" width="662" height="3" fill="#1a1022">
        <animate attributeName="opacity" values="0.4;1;0.4" dur="2.8s" repeatCount="indefinite" />
      </rect>
      <rect x="184" y="268" width={Math.min(662, 180 + snapshot.holders / 5)} height="3" fill="#ff3b9d" />
    </g>
  );
}

